import json
import re
import sys
from pathlib import Path

ROOT = Path(sys.argv[1])
S = "ledgers/CS2/scripts/CS2-d-r7/"
mut_lines = (ROOT / S / "r7_mutate_with_new.txt").read_text(encoding="utf-8").splitlines()
mutants = []
for ln in mut_lines:
    m = re.match(r"^(KILLED|SURVIVED) (\S+?\.py): (.*) -> (.*)$", ln)
    if not m:
        continue
    status, fname, desc, killed = m.groups()
    if status != "KILLED":
        raise SystemExit(f"survivor: {fname}")
    mutants.append({"id": fname[:-3], "description": desc, "killed_by": killed})
assert len(mutants) == 136, len(mutants)

